package app.awn.quran.tracker

import java.io.File
import org.json.JSONArray
import org.json.JSONObject

/**
 * Reads `ordered_quran_phonemes.json` (schema 2, generated by quran-transcript).
 *
 * Only two things in the file are used: the key of each entry in `verses` ("surah:ayah") and its
 * `aya_phonemes_list`, the phoneme string of each spoken word in order. A phoneme here is one
 * character of that string, because every character of the file is also a one-character symbol in
 * the model's `tokens.txt`; the model's longer tokens such as "بَ" are sequences of those
 * characters. The file is parsed once and only the word lists are kept.
 */
class JsonReferencePhonemes(json: String) : ReferencePhonemes {

    private val wordsByAyah: Map<Pair<Int, Int>, List<String>>
    private val maddsByAyah: Map<Pair<Int, Int>, List<List<MaddAnnotation>>>

    init {
        val root = JSONObject(json)
        val schema = root.getInt(SCHEMA_FIELD)
        require(schema == SUPPORTED_SCHEMA) { "Unsupported phoneme file schema $schema" }
        val verses = root.getJSONObject(VERSES_FIELD)
        val parsed = mutableMapOf<Pair<Int, Int>, List<String>>()
        val parsedMadds = mutableMapOf<Pair<Int, Int>, List<List<MaddAnnotation>>>()
        val verseKeys = verses.names() ?: JSONArray()
        for (keyIndex in 0 until verseKeys.length()) {
            val verseKey = verseKeys.getString(keyIndex)
            val (surahText, ayahText) = verseKey.split(KEY_SEPARATOR)
            val wordList = verses.getJSONObject(verseKey).getJSONArray(WORD_LIST_FIELD)
            val words = List(wordList.length()) { wordIndex -> wordList.getString(wordIndex) }
            val ayahKey = surahText.toInt() to ayahText.toInt()
            parsed[ayahKey] = words
            val rules = verses.getJSONObject(verseKey).optJSONArray(RULES_FIELD) ?: JSONArray()
            parsedMadds[ayahKey] = pairMaddRules(words, rules)
        }
        wordsByAyah = parsed
        maddsByAyah = parsedMadds
    }

    override fun forAyah(surah: Int, ayah: Int): List<ReferenceWord> {
        val words = wordsByAyah[surah to ayah] ?: return emptyList()
        return words.mapIndexed { wordIndex, word ->
            ReferenceWord(
                key = WordKeyLike(surah, ayah, wordPosition = wordIndex + 1),
                phonemes = word.map { phoneme -> phoneme.toString() },
                madds = maddsByAyah[surah to ayah]?.getOrNull(wordIndex).orEmpty(),
            )
        }
    }

    // `rules` holds [position, rule id, length] triples. The positions index a string that is not
    // in the file, so they are not used; but the madd rules (ids 1 to 6) come in the order of the
    // lengthened vowels (runs of two or more ا ۥ ۦ) in the phonemes, and the length of each rule
    // equals the length of its run. When the two lists disagree (a few ayahs with muqatta'at or
    // leen madd), the ayah gets no annotations rather than wrong ones.
    private fun pairMaddRules(words: List<String>, rules: JSONArray): List<List<MaddAnnotation>> {
        val ruleTriples = (0 until rules.length()).map { rules.getJSONArray(it) }
        val maddRules = ruleTriples.filter { it.getInt(RULE_ID_INDEX) in MADD_RULE_NAMES.keys }
        val runs =
            words
                .mapIndexed { wordIndex, word -> findMaddRuns(word).map { wordIndex to it } }
                .flatten()
        val agrees =
            runs.size == maddRules.size &&
                runs.indices.all {
                    maddRules[it].getInt(RULE_LENGTH_INDEX) == runs[it].second.length
                }
        val perWord = List(words.size) { mutableListOf<MaddAnnotation>() }
        if (!agrees) return perWord
        for ((index, run) in runs.withIndex()) {
            val (wordIndex, found) = run
            val ruleName = MADD_RULE_NAMES.getValue(maddRules[index].getInt(RULE_ID_INDEX))
            perWord[wordIndex] += MaddAnnotation(found.letter, ruleName, found.length, found.start)
        }
        return perWord
    }

    private class MaddRun(val letter: String, val start: Int, val length: Int)

    private fun findMaddRuns(word: String): List<MaddRun> {
        val runs = mutableListOf<MaddRun>()
        var position = 0
        while (position < word.length) {
            var end = position
            while (end < word.length && word[end] == word[position]) end++
            if (word[position] in MADD_LETTERS && end - position >= 2) {
                runs += MaddRun(word[position].toString(), position, end - position)
            }
            position = end
        }
        return runs
    }

    /** Returns every distinct phoneme the file uses, for checking against the model's tokens. */
    fun allPhonemes(): Set<String> =
        wordsByAyah.values.flatten().flatMap { word -> word.map { it.toString() } }.toSet()

    /** Returns the number of ayahs that have at least one word. */
    fun ayahCount(): Int = wordsByAyah.count { it.value.isNotEmpty() }

    companion object {
        private const val SUPPORTED_SCHEMA = 2
        private const val SCHEMA_FIELD = "schema"
        private const val VERSES_FIELD = "verses"
        private const val WORD_LIST_FIELD = "aya_phonemes_list"
        private const val KEY_SEPARATOR = ":"
        private const val RULES_FIELD = "rules"
        private const val RULE_ID_INDEX = 1
        private const val RULE_LENGTH_INDEX = 2
        private const val MADD_LETTERS = "اۥۦ"

        // Rule ids of the file's `rule_names`, 1 to 6; 7 (leen) and 8 (qalqalah) are not lengthened
        // vowels.
        private val MADD_RULE_NAMES =
            mapOf(
                1 to "natural",
                2 to "monfasel",
                3 to "mottasel",
                4 to "mottasel_waqf",
                5 to "aared",
                6 to "lazim",
            )

        fun fromFile(file: File): JsonReferencePhonemes = JsonReferencePhonemes(file.readText())
    }
}
